using System;
using System.Collections.Generic;
using UnityEngine;

namespace MassEngine
{
    /// <summary>Opt-in dynamic-enemy approach to real targets along existing legal cardinal routes.</summary>
    public static class TerrainLaneApproach33
    {
        public static void Apply(TerrainNavigationGrid nav, IReadOnlyList<Vector2> goals, Vector2[] directions, float stopRadius)
        {
            if (goals == null || goals.Count == 0) return;
            var rows = new List<int>[nav.ResolutionZ];
            var columns = new List<int>[nav.ResolutionX];
            Vector2 mean = Vector2.zero;
            int total = 0;
            foreach (var p in goals)
            {
                if (!nav.TryGetCell(p, out int cell) || !nav.IsWalkable(p)) continue;
                int x = cell % nav.ResolutionX, z = cell / nav.ResolutionX;
                if (rows[z] == null) rows[z] = new List<int>();
                if (columns[x] == null) columns[x] = new List<int>();
                rows[z].Add(cell); columns[x].Add(cell);
                mean += nav.CellCenter(cell); total++;
            }
            if (total == 0) return;
            mean /= total;
            foreach (var list in rows) list?.Sort();
            foreach (var list in columns) list?.Sort();
            float near = Mathf.Max(nav.CellSize * 4, stopRadius + nav.CellSize);
            int width = nav.ResolutionX;
            for (int cell = 0; cell < directions.Length; cell++)
            {
                Vector2 original = directions[cell];
                float ox = original.x, oz = original.y;
                if (ox * ox + oz * oz < .0001f) continue;
                Vector2 here = nav.CellCenter(cell);
                float towardX = mean.x - here.x, towardZ = mean.y - here.y;
                bool horizontal = Mathf.Abs(towardX) >= Mathf.Abs(towardZ);
                int sign = (horizontal ? towardX : towardZ) >= 0 ? 1 : -1;
                float px = horizontal ? sign : 0f, pz = horizontal ? 0f : sign;
                // Keep both terms: dropping the zero product would change NaN/Inf behavior.
                if (px * ox + pz * oz < .5f) continue;
                var list = horizontal ? rows[cell / width] : columns[cell % width];
                if (list == null) continue;
                int at = list.BinarySearch(cell);
                if (at < 0) at = ~at; else continue;
                int pick = sign > 0 ? at : at - 1;
                if (pick < 0 || pick >= list.Count) continue;
                int target = list[pick];
                if (Vector2.Distance(here, nav.CellCenter(target)) < near || !nav.HasClearCardinalRoute33(cell, target)) continue;
                directions[cell] = new Vector2(px, pz);
            }
        }
    }
}

